codeExamples.code:
// Source code:
let x = 2 + 3;

// AST structure (simplified):
// VariableDeclaration
//   name: "x"
//   init: BinaryExpression
//     operator: "+"
//     left: NumericLiteral(2)
//     right: NumericLiteral(3)

// Source: let x = 2 + 3;
// Ignition bytecode (simplified):
// Star r0, 2        // Load 2 into register 0
// Star r1, 3        // Load 3 into register 1
// Add r0, r0, r1    // r0 = r0 + r1
// Star r2, r0       // Store result in r2 (x)

// TurboFan optimizes this (consistent types)
function add(a, b) {
  return a + b;
}

// Called many times with numbers → optimized
for (let i = 0; i < 10000; i++) {
  add(i, i + 1);  // TurboFan: "both args are integers"
}

// Now call with strings → DEOPTIMIZATION!
add("hello", "world");  // TurboFan: "wrong types!"
// Engine falls back to Ignition bytecode

// ❌ Changing object shape
let obj = { x: 1 };
obj.y = 2;  // new shape → deoptimization

// ❌ Mixed-type arrays
let arr = [1, 2, 3];
arr.push("four");  // now mixed types

// ✅ Consistent types
let arr2 = [1, 2, 3];
arr2.push(4);  // still all numbers ✓

// ✅ Consistent object shape
let obj2 = { x: 1, y: undefined };
obj2.y = 2;  // same shape ✓
